const std = @import("std");
const mem = std.mem;
const fs = std.fs;
const http = std.http;
const json = std.json;
const time = std.time;
const math = std.math;
const crypto = std.crypto;
const Sha256 = std.crypto.hash.sha2.Sha256;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;
const HashMap = std.HashMap;
const RingBuffer = std.RingBuffer(u8, 1024 * 1024);

const ConversationChar = packed struct {
    char: u8,
    pos: u32,
    timestamp: i64,
    hash: [8]u8,
    surprise_score: f32,
};

const ConversationHistory = struct {
    allocator: Allocator,
    chars: ArrayList(ConversationChar),
    char_hashes: HashMap([32]u8, void, Sha256, std.hash_map.default_max_load_percentage),
    ring_buffer: RingBuffer,
    filename: []const u8,
    total_chars: usize = 0,
    session_id: [16]u8,

    pub fn init(allocator: Allocator, filename: []const u8) !ConversationHistory {
        var self: ConversationHistory = .{
            .allocator = allocator,
            .chars = ArrayList(ConversationChar).init(allocator),
            .char_hashes = HashMap([32]u8, void, Sha256, std.hash_map.default_max_load_percentage).init(allocator),
            .ring_buffer = RingBuffer.init(),
            .filename = try allocator.dupe(u8, filename),
            .session_id = undefined,
        };
        crypto.random.bytes(&self.session_id);
        try self.loadFromFile();
        return self;
    }

    pub fn deinit(self: *ConversationHistory) void {
        self.chars.deinit();
        self.char_hashes.deinit();
        self.allocator.free(self.filename);
        self.saveToFile() catch {};
    }

    fn loadFromFile(self: *ConversationHistory) !void {
        const file = fs.cwd().openFile(self.filename, .{ .mode = .read_write }) catch fs.cwd().createFile(self.filename, .{});
        defer file.close();
        var reader = file.reader();
        var buf: [1024]u8 = undefined;
        while (true) {
            const n = try reader.read(&buf);
            if (n == 0) break;
            // Parse binary format: char(1)+pos(4)+ts(8)+hash(32)+score(4)
            var i: usize = 0;
            while (i + 49 <= n) {
                const ch: ConversationChar = .{
                    .char = buf[i],
                    .pos = mem.readIntLittle(u32, &buf[i+1]),
                    .timestamp = mem.readIntLittle(i64, &buf[i+5]),
                    .hash = mem.bytesToValue([32]u8, buf[i+13..i+45]),
                    .surprise_score = mem.readIntLittle(f32, &buf[i+45]),
                };
                try self.chars.append(ch);
                _ = try self.char_hashes.put(ch.hash, {});
                self.total_chars += 1;
                i += 49;
            }
        }
    }

    fn saveToFile(self: *ConversationHistory) !void {
        const file = try fs.cwd().openFile(self.filename, .{ .mode = .read_write });
        defer file.close();
        var writer = file.writer();
        for (self.chars.items) |ch| {
            try writer.writeIntLittle(u8, ch.char);
            try writer.writeIntLittle(u32, ch.pos);
            try writer.writeIntLittle(i64, ch.timestamp);
            try writer.writeAll(&ch.hash);
            try writer.writeIntLittle(f32, ch.surprise_score);
        }
    }

    fn computeSurprise(self: *ConversationHistory, prev_char: u8, curr_char: u8) f32 {
        const dist = math.absCast(@as(i32, prev_char) - @as(i32, curr_char));
        return @as(f32, @floatFromInt(dist)) / 255.0 + 0.1; // 0-1 score, higher=more surprise
    }

    pub fn forceReadAndMemorize(self: *ConversationHistory, text: []const u8) !void {
        var prev_char: u8 = 0;
        var i: usize = 0;
        while (i < text.len) : (i += 1) { // KÉNYSZERÍTETT char-by-char loop - NEM UGRATHATÁT!
            const curr_char = text[i];
            if (!std.ascii.isPrint(curr_char) and curr_char != '\n' and curr_char != '\t') continue;

            // UTF-8 multibyte skip
            var char_bytes: usize = 1;
            if ((curr_char & 0xC0) == 0xC0) {
                char_bytes = std.utf8.countCodepointBytes(curr_char);
                if (i + char_bytes > text.len) break;
            }

            var hasher = Sha256.init(.{});
            hasher.update(&self.session_id);
            hasher.update(text[i..std.math.min(i + char_bytes, text.len)]);
            var hash: [32]u8 = undefined;
            hasher.final(&hash);

            if (self.char_hashes.contains(hash)) continue; // Duplicate skip, de memorizált!

            const ts = time.timestamp();
            const pos = @intCast(u32, i);
            const surprise = self.computeSurprise(prev_char, curr_char);
            const ch: ConversationChar = .{ .char = curr_char, .pos = pos, .timestamp = ts, .hash = hash[0..8].*, .surprise_score = surprise };

            try self.chars.append(ch);
            _ = try self.char_hashes.put(hash, {});
            self.ring_buffer.writeItem(curr_char) catch {}; // Ring buffer overflow auto-evict
            self.total_chars += 1;
            prev_char = curr_char;

            // SIMD batch surprise update ihletés vpu.txt-ből
            if (self.total_chars % 64 == 0) {
                self.updateSurpriseRankings() catch {};
            }
        }
        try self.saveToFile();
    }

    fn updateSurpriseRankings(self: *ConversationHistory) !void {
        // Quick sort top-surprise chars for priority recall
        std.sort.insertion(ConversationChar, self.chars.items, {}, struct {
            fn lessThan(_: void, a: ConversationChar, b: ConversationChar) bool {
                return a.surprise_score > b.surprise_score;
            }
        }.lessThan);
    }

    pub fn dumpToJson(self: *ConversationHistory, alloc: Allocator) ![]u8 {
        var history_text = ArrayList(u8).init(alloc);
        defer history_text.deinit();
        for (self.chars.items) |ch| {
            try history_text.append(ch.char);
        }
        const summary = try std.fmt.allocPrint(alloc, "Session: {}, Total chars: {}, Surprise avg: {:.2}", .{ std.fmt.fmtSliceHexLower(&self.session_id), self.total_chars, std.sort.reduce(f32, self.chars.items, {}, struct { fn f(_: void, a: f32, b: f32) f32 { return @min(a, b); } }.f) });
        return try std.fmt.allocPrint(alloc, "Full history dump ({} chars): {} | Summary: {}", .{ self.total_chars, history_text.items, summary });
    }
};

const APIRequest = struct {
    model: []const u8 = "xiaomi/mimo-v2.5-pro",
    messages: []struct { role: []const u8, content: []const u8 },
};

const APIResponse = struct {
    choices: [1]struct {
        message: struct {
            content: []const u8,
        },
    },
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const history = try ConversationHistory.init(allocator, "conversation.zigdb");
    defer history.deinit();

    // Példa user input - appodba integráld stdin vagy arg-ként
    const user_text = "Mit tud a transformers LLM Zig plugin?";

    // 1. KÉNYSZERÍTETT CHAR-BY-CHAR OLVASÁS ÉS MEMORizálÁS
    std.debug.print("Force reading char-by-char: '{s}'\n", .{user_text});
    try history.forceReadAndMemorize(user_text);

    // 2. History dump JSON inject a system message-be
    const history_json = try history.dumpToJson(allocator);
    defer allocator.free(history_json);

    // 3. API request építés - history ALWAYS injectálva
    var messages = [_]struct { role: []const u8, content: []const u8 }{
        .{ .role = "system", .content = "You are a helpful assistant. Full conversation history:" },
        .{ .role = "system", .content = history_json }, // INJECT!
        .{ .role = "user", .content = user_text },
    };

    var body_stream = std.json.writeStream(std.ArrayList(u8).init(allocator).writer(), .{ .allocator = allocator }, .{ .model = history.model, .messages = &messages }, .{});
    defer body_stream.deinit();
    const body_bytes = try body_stream.list.toOwnedSlice();

    // 4. A TE eredeti HTTP client - most history-aware
    var client = http.Client{ .allocator = allocator };
    defer client.deinit();
    const uri = try std.Uri.parse("");

    const headers = [_]http.Header{
        .{ .name = "content-type", .value = "application/json" },
        .{ .name = "authorization", .value = "Bearer <Your API Key>" }, // Cseréld!
    };

    var req = try client.open(.POST, uri, .{ .headers = headers });
    req.transfer_encoding = .{ .content_length = body_bytes.len };
    try req.send();
    try req.writer().writeAll(body_bytes);
    try req.finish();
    try req.wait();

    if (req.response.status_code != 200) return error.APIError;

    const resp_body = try req.reader().readAllAlloc(allocator, 1024 * 1024);
    defer allocator.free(resp_body);

    var parsed = try std.json.parseFromSlice(APIResponse, allocator, resp_body, .{});
    defer parsed.deinit();

    const content = parsed.value.choices[0].message.content orelse "No response";
    std.debug.print("Model response (after forced memory): {s}\n", .{content});

    // 5. Response-t is memorizáljuk char-by-char!
    try history.forceReadAndMemorize(content);
